use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = stock.inventory();
    var result = "";
    var first = true;

    for plank in planks {
        if rules.keep(plank) {
            let label = rules.label(plank);
            if first {
                result = label;
                first = false;
            } else {
                result = result.concat(other: ",").concat(other: label);
            }
        }
    }

    result
}

