use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;

    for frame in feed.frames() {
        let value = match feed.decode(frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + value;
    }

    feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;

    while i < frames.len() {
        let value = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }

    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

